// ../maestro-sdk/src/query-string.ts
function buildQueryString(params) {
  const entries = [];
  for (const [key, value] of Object.entries(params)) {
    if (value === undefined)
      continue;
    if (Array.isArray(value)) {
      for (const item of value) {
        entries.push([key, item]);
      }
      continue;
    }
    entries.push([key, String(value)]);
  }
  if (entries.length === 0)
    return "";
  return `?${new URLSearchParams(entries).toString()}`;
}

// ../maestro-sdk/src/with-debug-pims-call.ts
async function createDebugPimsConfig() {
  const status = await getLoginStatusAsync({
    ensureTokenValidityMinutes: 10
  });
  if (status.loginStatus !== "Logged in" || !status.baseUrl || !status.accessToken) {
    throw new Error(status.hint ? `Not logged in. ${status.hint}` : "Not logged in. Run 'uip login' first.");
  }
  if (!status.organizationId) {
    throw new Error("Organization ID not available. Ensure you are logged in with an organization context.");
  }
  if (!status.tenantId) {
    throw new Error("Tenant ID not available. Ensure UIPATH_TENANT_ID is set.");
  }
  if (!status.tenantName) {
    throw new Error("Tenant name not available. Ensure you are logged in with a tenant context.");
  }
  return {
    baseUrl: status.baseUrl,
    organizationId: status.organizationId,
    tenantName: status.tenantName,
    tenantId: status.tenantId,
    authToken: status.accessToken
  };
}
async function withDebugPimsCall(fn, errorMessage) {
  const [configError, config] = await catchError(createDebugPimsConfig());
  if (configError) {
    logger.warn(`${errorMessage}: ${configError.message}`);
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: errorMessage,
      Instructions: configError.message
    });
    processContext.exit(1);
    return;
  }
  if (!config.folderKey) {
    const [folderError, folder] = await catchError(getPersonalFolderKey(config));
    if (folderError) {
      logger.warn(`Could not resolve personal folder: ${folderError.message}`);
    } else {
      config.folderKey = folder.key;
      config.organizationUnitId = folder.id;
    }
  }
  const [error, result] = await catchError(fn(config));
  if (error) {
    const msg = await extractErrorMessage(error);
    logger.warn(`${errorMessage}: ${msg}`);
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: errorMessage,
      Instructions: msg
    });
    processContext.exit(1);
    return;
  }
  return result;
}

