function parseBackendErrorBody(body) {
  if (!body)
    return {};
  const [parseErr, parsed] = catchError(() => JSON.parse(body));
  if (parseErr || !parsed || typeof parsed !== "object")
    return {};
  const result = {};
  if (typeof parsed.message === "string")
    result.message = parsed.message;
  if (typeof parsed.errorCode === "number" || typeof parsed.errorCode === "string") {
    result.errorCode = String(parsed.errorCode);
  }
  if (typeof parsed.traceId === "string")
    result.traceId = parsed.traceId;
  if (typeof parsed.requestId === "string") {
    result.requestId = parsed.requestId;
  }
  return result;
}

class PimsApiError extends Error {
  method;
  endpoint;
  url;
  httpStatus;
  statusText;
  body;
  parsedErrorMessage;
  parsedErrorCode;
  parsedTraceId;
  parsedRequestId;
  constructor(details) {
    const parsed = parseBackendErrorBody(details.body);
    const messageSuffix = parsed.message ? ` - ${parsed.message}` : "";
    super(`PIMS API request failed: ${details.httpStatus} ${details.statusText} on ${details.method} ${details.endpoint}${messageSuffix}`);
    this.name = "PimsApiError";
    this.method = details.method;
    this.endpoint = details.endpoint;
    this.url = details.url;
    this.httpStatus = details.httpStatus;
    this.statusText = details.statusText;
    this.body = details.body;
    this.parsedErrorMessage = parsed.message;
    this.parsedErrorCode = parsed.errorCode;
    this.parsedTraceId = parsed.traceId;
    this.parsedRequestId = parsed.requestId;
  }
}
